    /// `JsKvItem[]`, at most `max` items.
    pub(crate) fn kv_items(&mut self, items: &List<'_>, max: usize) -> napi::Result<Vec<JsKvItem>> {
        check_len("items", items.len(), max)?;
        let mut out = Vec::with_capacity(items.len());
